"use strict";(globalThis.webpackChunksite=globalThis.webpackChunksite||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"portfolioSidebar":[{"type":"link","href":"/docs/intro","label":"Home","docId":"intro","unlisted":false},{"type":"link","href":"/docs/about","label":"About","docId":"about","unlisted":false},{"type":"category","label":"Approach","items":[{"type":"link","href":"/docs/portfolio/overview","label":"How I Work","docId":"portfolio/overview","unlisted":false},{"type":"link","href":"/docs/portfolio/tools-and-systems","label":"Tools and Systems","docId":"portfolio/tools-and-systems","unlisted":false}],"collapsed":false,"collapsible":true},{"type":"category","label":"Case Studies","items":[{"type":"link","href":"/docs/case-studies/overview","label":"Work Overview","docId":"case-studies/overview","unlisted":false},{"type":"link","href":"/docs/case-studies/teracreators-help","label":"TeraCreators Help","docId":"case-studies/teracreators-help","unlisted":false},{"type":"link","href":"/docs/case-studies/documentation-operations","label":"Documentation Operations","docId":"case-studies/documentation-operations","unlisted":false},{"type":"link","href":"/docs/case-studies/migrations-and-ia","label":"Migrations and Information Architecture","docId":"case-studies/migrations-and-ia","unlisted":false},{"type":"link","href":"/docs/case-studies/analytics-and-reporting","label":"Analytics and Reporting","docId":"case-studies/analytics-and-reporting","unlisted":false},{"type":"link","href":"/docs/case-studies/documentation-tooling-and-automation","label":"Documentation Tooling and Automation","docId":"case-studies/documentation-tooling-and-automation","unlisted":false}],"collapsed":false,"collapsible":true},{"type":"category","label":"Writing Samples","items":[{"type":"link","href":"/docs/writing-samples/overview","label":"Writing and Content Strategy","docId":"writing-samples/overview","unlisted":false}],"collapsed":false,"collapsible":true},{"type":"category","label":"Data & Analytics","items":[{"type":"link","href":"/docs/data-analytics/overview","label":"Documentation Analytics","docId":"data-analytics/overview","unlisted":false}],"collapsed":false,"collapsible":true},{"type":"category","label":"Experience","items":[{"type":"link","href":"/docs/experience/selected-achievements","label":"Selected Achievements","docId":"experience/selected-achievements","unlisted":false},{"type":"link","href":"/docs/experience/work-history","label":"Work History","docId":"experience/work-history","unlisted":false},{"type":"link","href":"/docs/experience/leadership-and-mentoring","label":"Leadership and Mentoring","docId":"experience/leadership-and-mentoring","unlisted":false}],"collapsed":false,"collapsible":true},{"type":"category","label":"Selected Projects","items":[{"type":"link","href":"/docs/projects/vinyl-junction","label":"Vinyl Junction","docId":"projects/vinyl-junction","unlisted":false}],"collapsed":false,"collapsible":true}]},"docs":{"about":{"id":"about","title":"About","description":"I\u2019m a Senior Documentation Engineer. I help teams make complicated products and operational systems easier to understand, navigate, maintain, and improve.","sidebar":"portfolioSidebar"},"case-studies/analytics-and-reporting":{"id":"case-studies/analytics-and-reporting","title":"Analytics and Reporting","description":"Documentation teams usually know when something is off. The harder part is seeing the pattern clearly enough to decide what to change.","sidebar":"portfolioSidebar"},"case-studies/documentation-operations":{"id":"case-studies/documentation-operations","title":"Documentation Operations","description":"Good documentation needs more than good pages. It needs enough structure around the pages for teams to plan work, keep standards visible, and maintain the system as products change.","sidebar":"portfolioSidebar"},"case-studies/documentation-tooling-and-automation":{"id":"case-studies/documentation-tooling-and-automation","title":"Documentation Tooling and Automation","description":"Documentation work accumulates small, repeated jobs: checking changes, finding stale pages, routing reviews, publishing updates, and keeping standards visible. At scale, those jobs become part of the documentation system.","sidebar":"portfolioSidebar"},"case-studies/migrations-and-ia":{"id":"case-studies/migrations-and-ia","title":"Migrations and Information Architecture","description":"Many documentation problems are structure problems. The content exists, but it is hard to find, shaped by old organizational history, or expensive to maintain.","sidebar":"portfolioSidebar"},"case-studies/overview":{"id":"case-studies/overview","title":"Work Overview","description":"This section highlights work where the challenge involved structure, scale, evolving systems, or uneven source material. The common thread is turning documentation from a collection of pages into something people can use and teams can sustain.","sidebar":"portfolioSidebar"},"case-studies/teracreators-help":{"id":"case-studies/teracreators-help","title":"TeraCreators Help","description":"TeraCreators Help is a public documentation project covering multiple games. It turns scattered, fast-moving community knowledge into a structured help system people can navigate and contributors can extend.","sidebar":"portfolioSidebar"},"data-analytics/content-audits":{"id":"data-analytics/content-audits","title":"Documentation Analytics","description":""},"data-analytics/dashboards-and-reporting":{"id":"data-analytics/dashboards-and-reporting","title":"Documentation Analytics","description":""},"data-analytics/excel-and-power-query":{"id":"data-analytics/excel-and-power-query","title":"Documentation Analytics","description":""},"data-analytics/measurement-and-operations":{"id":"data-analytics/measurement-and-operations","title":"Documentation Analytics","description":""},"data-analytics/overview":{"id":"data-analytics/overview","title":"Documentation Analytics","description":"I use analytics to improve documentation work, not to decorate it with dashboards. The useful question is always practical: what does a team need to see in order to prioritize, maintain, or improve the system?","sidebar":"portfolioSidebar"},"experience/leadership-and-mentoring":{"id":"experience/leadership-and-mentoring","title":"Leadership and Mentoring","description":"My leadership work has been about helping people produce stronger documentation in a more consistent, sustainable way. That means quality and coaching, but also the standards, workflows, and visibility that let a team do good work without relying on heroic effort.","sidebar":"portfolioSidebar"},"experience/overview":{"id":"experience/overview","title":"Selected Achievements","description":""},"experience/selected-achievements":{"id":"experience/selected-achievements","title":"Selected Achievements","description":"Scale at a glance","sidebar":"portfolioSidebar"},"experience/work-history":{"id":"experience/work-history","title":"Work History","description":"My career has followed a consistent pattern: take complicated products, unclear workflows, or fragmented knowledge and make them clearer, more usable, and easier to maintain.","sidebar":"portfolioSidebar"},"intro":{"id":"intro","title":"Home","description":"Adam Pugh","sidebar":"portfolioSidebar"},"portfolio/overview":{"id":"portfolio/overview","title":"How I Work","description":"I\u2019m a Senior Documentation Engineer. I work where content, product change, and operational reality meet: turning scattered knowledge into useful help, making large documentation environments easier to govern, and building practical systems that reduce maintenance work.","sidebar":"portfolioSidebar"},"portfolio/problem-solving":{"id":"portfolio/problem-solving","title":"How I Work","description":""},"portfolio/tools-and-systems":{"id":"portfolio/tools-and-systems","title":"Tools and Systems","description":"I use tools to improve a documentation system, not to collect a longer skills list. The useful question is always: where is the friction, and what combination of structure, process, and tooling will make the work easier to maintain?","sidebar":"portfolioSidebar"},"projects/personal-site":{"id":"projects/personal-site","title":"Tools and Systems","description":""},"projects/vinyl-junction":{"id":"projects/vinyl-junction","title":"Vinyl Junction","description":"Vinyl Junction is my Etsy shop for vintage music and books. It is not enterprise documentation, but it is a long-running customer-facing information and operations system\u2014and a real example of the habits that also matter in documentation work.","sidebar":"portfolioSidebar"},"writing-samples/edited-enterprise-samples":{"id":"writing-samples/edited-enterprise-samples","title":"Writing and Content Strategy","description":""},"writing-samples/overview":{"id":"writing-samples/overview","title":"Writing and Content Strategy","description":"The strongest writing work on this site is not a stack of detached samples. It is the judgment behind a useful page: choosing the right form, explaining the right amount, and maintaining the content as the system changes.","sidebar":"portfolioSidebar"}}}}')}}]);